        text = segment['text']
        start = segment['start']
        end = segment['end']
        duration = end - start

        if current_start is None:
            current_start = start

        if current_segment:
            current_segment += " "

        current_segment += text
        current_duration += duration

        if current_duration >= cut_duration_seconds and is_end_of_sentence(text):
            conversation_segments.append({
                'text': current_segment.strip(),
                'start': current_start,
                'end': end
            })
            current_segment = ""
            current_start = None
            current_duration = 0

    if current_segment:
        conversation_segments.append({
            'text': current_segment.strip(),
            'start': current_start,
            'end': end
        })

    return conversation_segments

def get_hwid():
    c = wmi.WMI()
    serial_number = None
    for disk in c.Win32_DiskDrive():
        serial_number = disk.SerialNumber.strip()
        break
    if serial_number is None:
        raise ValueError("Não foi possível Gerar o HWID.")
    uuid_hash = hashlib.md5(serial_number.encode('utf-8')).hexdigest()
    formatted_uuid = f"{uuid_hash[:8]}-{uuid_hash[8:12]}-{uuid_hash[12:16]}-{uuid_hash[16:20]}-{uuid_hash[20:]}"
    return formatted_uuid

def check_hwid_local(hwid):
    hwids_autorizados = [
        "",  # Adicione os HWIDs autorizados aqui
    ]
    return hwid in hwids_autorizados

def check_hwid_online(hwids_url, hwid):
    try:
        response = requests.get(hwids_url)
        if response.status_code == 200:
            hwids = response.text.strip().split('\n')
            if hwid in hwids:
                return True
            else:
                return False
        else:
            print(f"Erro ao acessar Link: {response.status_code}")
            return False
    except requests.exceptions.RequestException as e:
        print(f"Erro de requisição: {e}")
        return False

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc, result.path])
    except ValueError:
        return False

def normalize_url(url):
    if not url.startswith('http://') and not url.startswith('https://'):
        url = 'https://'+url
    return url

def download_video(url, output_path='video.mp4', max_attempts=10):
    if not is_valid_url(url):
        raise ValueError("Link inválido. Verifique o Link e tente novamente.")
    url = normalize_url(url)
    attempts = 0
    while attempts < max_attempts:
        try:
            print(f"Tentativa de download {attempts + 1}…")
            ydl_opts = {
                'format': 'bestvideo[height>=720][ext=mp4]+bestaudio[ext=m4a]/best[height>=720][ext=mp4]+bestaudio[ext=m4a]',
                'outtmpl': output_path,
                'quiet': False
            }
            with youtube_dl.YoutubeDL(ydl_opts) as ydl:
                info_dict = ydl.extract_info(url, download=True)
                print(f'Título do vídeo: {info_dict.get("title", "N/A")}')
                return info_dict.get('title', 'N/A')
        except Exception as e:
            print(f"Erro ao baixar vídeo: {e}")
            attempts += 1
            time.sleep(2)
    print(f"Não foi possível baixar o vídeo após {max_attempts} tentativas. Encerrando o programa.")
    raise RuntimeError("Falha ao baixar o vídeo após várias tentativas.")

def resize_and_crop_vertical(clip):
    target_width = 1080
    target_height = 1920
    def process_frame(frame):
        frame_height, frame_width = frame.shape[:2]
        aspect_ratio = frame_width / frame_height
        target_aspect_ratio = target_width / target_height
        if (aspect_ratio < target_aspect_ratio):
            new_width = target_width
            new_height = int(target_width / aspect_ratio)
            resized_frame = cv2.resize(frame, (new_width, new_height))
            crop_y = (new_height - target_height) // 2
            return resized_frame[crop_y:crop_y + target_height, :]
        else:
            new_height = target_height
            new_width = int(target_height * aspect_ratio)
            resized_frame = cv2.resize(frame, (new_width, new_height))
            crop_x = (new_width - target_width) // 2
            return resized_frame[:, crop_x:crop_x + target_width]
    return clip.fl_image(process_frame)

def resize_and_crop_horizontal(clip):
    target_width = 1920
    target_height = 1080
    def process_frame(frame):
        frame_height, frame_width = frame.shape[:2]
        aspect_ratio = frame_width / frame_height
        target_aspect_ratio = target_width / target_height
        if aspect_ratio > target_aspect_ratio:
            new_height = target_height
            new_width = int(target_height * aspect_ratio)
            resized_frame = cv2.resize(frame, (new_width, new_height))
            crop_x = (new_width - target_width) // 2
            return resized_frame[:, crop_x:crop_x + target_width]
        else:
            new_width = target_width
            new_height = int(target_width / aspect_ratio)
            resized_frame = cv2.resize(frame, (new_width, new_height))
            crop_y = (new_height - target_height) // 2
            return resized_frame[crop_y:crop_y + target_height, :]
    return clip.fl_image(process_frame)

def cut_video(video_path, segments, vertical_format=True, title=""):
    print("Iniciando o Corte de Vídeo…")
    video = VideoFileClip(video_path)
    for i, segment in enumerate(segments):
        start = segment['start']
        end = segment['end']
        cut = video.subclip(start, end)

        if vertical_format:
            cut = resize_and_crop_vertical(cut)
        else:
            cut = resize_and_crop_horizontal(cut)

        # Aqui mantenho o título do vídeo com espaços e adiciono a numeração
        output_filename = f"{title} #{i + 1}.mp4"
        cut.write_videofile(output_filename, codec='libx264')
        print(f'Segmento {i + 1} salvo como {output_filename}')
    video.close()
    print("Corte de Vídeo Completo.")


def automatic_cut(video_length, vertical_format=True):
    print(f"Em automatic_cut: {video_length}, vertical_format: {vertical_format}")
    if vertical_format:
        if video_length < 600:
            min_total_duration = 30
            max_total_duration = 60
        elif 600 <= video_length <= 1800:
            min_total_duration = 30
            max_total_duration = 60
        elif video_length > 1800:
            min_total_duration = 60
            max_total_duration = 120
        else:
            raise ValueError("Vídeo fora do intervalo de duração suportado.")
    else:
        if 600 <= video_length <= 1800:
            min_total_duration = 300
            max_total_duration = 300
        elif video_length > 1800:
            min_total_duration = 600
            max_total_duration = 1200
        else:
            raise ValueError("Vídeo fora do intervalo de duração suportado.")

    min_duration = random.randint(min_total_duration, max_total_duration)
    max_duration = random.randint(min_total_duration, max_total_duration)

    print(f"Retornando min_duration: {min_duration}, max_duration: {max_duration}")
    return min_duration, max_duration

